        setStatus('Unable to delete note.', true);
        return;
      }
      setStatus('Note deleted.');
      resetForm();
      await fetchNotes();
    });
  });
}

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

